/**
 * Shape of `data/registry.json`: everything the MCP server knows about the c2n components, generated by
 * `scripts/build-registry.ts` from the component manifests, the docs site content and the theme package.
 */
export interface Registry {
  schemaVersion: 1
  /** lerna.json version of the published packages. */
  c2nVersion: string
  categories: string[]
  /** Keyed by component id (the docs page id: `button`, `feather-icons`, `chatbot`). */
  components: Record<string, ComponentEntry>
  /** Tag → component id (`c2-tab` → `tabs`). Icon tags resolve through `tagPattern`. */
  tagIndex: Record<string, string>
  /** npm package → component id. */
  packageIndex: Record<string, string>
  theme: ThemeEntry
  guides: Record<GuideTopic, string>
}

export type GuideTopic = 'workflow' | 'theming' | 'variant-components' | 'frameworks'

export interface ComponentEntry {
  id: string
  package: string
  title: string
  description: string
  intro?: string
  category: string
  /** `stable` has a docs page; `undocumented` is published and built but has no page yet. */
  status: 'stable' | 'undocumented'
  docsUrl: string
  /** One entry per custom element in the package (`tabs` has `c2-tabs` and `c2-tab`). */
  elements: ElementEntry[]
  /** Icon sets: the tag pattern (`c2-feather-{name}`) and the icon names. */
  tagPattern?: string
  icons?: string[]
  composition: { internal: string[]; slotted: string[]; usedBy: string[] }
  install: { npm: string; import: string; importClass: string }
  presets?: { html: string; items: Preset[] }
  examples: Example[]
  hasGallery: boolean
}

export interface ElementEntry {
  tag: string
  className: string
  /** Import specifier of the module defining the element, e.g. `@c2n/tabs/tab.js`. */
  modulePath: string
  description: string
  attributes: { name: string; type: string; default?: string; description?: string }[]
  slots: { name: string; description?: string }[]
  events: { name: string; type?: string; description?: string }[]
  cssProperties: CssProperty[]
}

export interface CssProperty {
  name: string
  type: string
  default?: string
  /** Part segment(s) joined with `/`, `''` for the root. */
  part: string
  state?: string
  property: string
  /** `--c2-theme--*` token the base theme maps this variable to, when any. */
  token?: string
  description?: string
}

export interface Example {
  kind: 'usage' | 'gallery' | 'preview'
  label: string
  section?: string
  html: string
  css?: string
}

export interface Preset {
  name: string
  description?: string
  css: Record<string, string>
  attributes?: Record<string, string>
}

export interface ThemeToken {
  name: string
  category: string
  light: string | null
  dark?: string
  description: string
  /** Number of component variables mapped to this token. */
  usedBy: number
}

export interface ThemeEntry {
  package: string
  install: { npm: string; imports: string[] }
  tokens: ThemeToken[]
  /** Component variable → token. */
  mapping: Record<string, string>
  darkMode: string
}
